import{z as A,x as d,o as r,c as p,q as t,j as n,D as i,d as o,s as E,S as s,b as e}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"DFA 最小化与 Myhill–Nerode","description":"","frontmatter":{"title":"DFA 最小化与 Myhill–Nerode","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/dfa-minimization.md","filePath":"cs/dfa-minimization.md","lastUpdated":1791413859000}'),B={name:"cs/dfa-minimization.md"};function m(f,a,D,h,F,u){const l=d("Mermaid");return r(),p("div",null,[a[2]||(a[2]=t('<h1 id="dfa-最小化与-myhill–nerode" tabindex="-1">DFA 最小化与 Myhill–Nerode <a class="header-anchor" href="#dfa-最小化与-myhill–nerode" aria-label="Permalink to &quot;DFA 最小化与 Myhill–Nerode&quot;">​</a></h1><div class="epigraph"><p>正则语言对应字母表上的有限指数右同余；等价类就是最小 DFA 的状态，个数是语言的固有不变量。</p><footer>—— 据 Nerode, Linear Automaton Transformations, 1958；Hopcroft, 1971 整理</footer></div><p>上一课<a href="/cs/pumping-lemma-regular">泵引理</a>给出排除正则的必要性质，并点名「有些非正则可泵」。本课不重写博弈。缺口是<strong>充要刻画</strong>：Myhill–Nerode 等价类有限当且仅当语言正则，并且最小 DFA 在同构意义下唯一。主干<a href="/cs/nfa-dfa">NFA/DFA</a>只说过「确定化之后可再压状态」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>同一正则语言可以有许多 DFA，状态数从子集构造的 \\(2^{|Q|}\\) 到「刚好够用」。何谓够用？对 \\(x,y\\in\\Sigma^*\\)，定义 \\(x\\sim_L y\\) 当且仅当 \\(\\forall z,\\ xz\\in L\\iff yz\\in L\\)。这是右同余。指数（等价类个数）有限 \\(\\iff\\) \\(L\\) 正则。每个类做成一个状态，\\(\\delta([x],a)=[xa]\\)，接受类是那些 \\(x\\in L\\)。</p><p>泵引理看不到「两个前缀是否永远可互换」。\\(\\{a^nb^n\\}\\) 的前缀 \\(a^i\\) 两两不等价（后面跟 \\(b^i\\) 才能分），指数无穷，故非正则——这补上泵失败时的工具。</p><p><span class="marginnote">直觉类比：把等价类想成对「前缀处境」的分类——两个前缀若往后接任何字符串命运都相同，就归同一类、共用一个状态。等价类个数就是机器「最少要记住几种处境」，处境有无穷多种，有限状态就装不下。</span></p><h3 id="最小不是「看起来少」" tabindex="-1">最小不是「看起来少」 <a class="header-anchor" href="#最小不是「看起来少」" aria-label="Permalink to &quot;最小不是「看起来少」&quot;">​</a></h3><p>任意 DFA 可按可区分性合并：两状态 \\(p,q\\) 可区分，若存在 \\(z\\) 使恰好一个走到接受。Hopcroft 划分细化给出 \\(O(|Q||\\Sigma|\\log|Q|)\\) 算法。最小化结果与 Nerode 自动机同构。少一个状态就会认错语言。</p><p><span class="marginnote">Nerode 1958；Myhill 的同余更偏句法。Hopcroft 1971 最小化是词法生成器的标准步骤。本课要的是不变量 \\(|Q_{\\min}|\\)，不手写全部划分表。</span></p><p><span class="marginnote">术语翻译：「可区分」就是存在一根续接尾巴 \\(z\\) 能把两个状态分开——从 \\(p\\) 读 \\(z\\) 会接受、从 \\(q\\) 读 \\(z\\) 会拒绝。以 aa 结尾的自动机里，状态 A（什么都没读）和 B（刚读完 a）用 \\(z=a\\) 即可区分：Aaa 拒绝，Baa 接受，所以 A、B 必须是两个状态。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对给定 \\(L\\)，尝试列出无穷多两两可区分的前缀，即证非正则。对给定 DFA，算不可区分划分，商自动机即最小。不要把 NFA 最小化当多项式问题——NFA 最小状态数是难的，本课对象是 DFA。</p>',13)),(r(),n(s,null,{default:i(()=>[E(l,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20L%5B%22%E8%AF%AD%E8%A8%80%20L%22%5D%20--%3E%20MN%5B%22Nerode%20%E7%AD%89%E4%BB%B7%E7%B1%BB%22%5D%0A%20%20MN%20--%3E%20MIN%5B%22%E6%9C%80%E5%B0%8F%20DFA%22%5D%0A%20%20DFA%5B%22%E4%BB%BB%E6%84%8F%20DFA%22%5D%20--%3E%20PART%5B%22%E5%8F%AF%E5%8C%BA%E5%88%86%E5%88%92%E5%88%86%22%5D%0A%20%20PART%20--%3E%20MIN%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,[e("a",{href:"/cs/thompson-nfa"},"Thompson"),o(" 与子集构造之后接本课，才得到词法器里那张紧表。本补层不重做构造，只收等价类。")],-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[o("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"\\(|Q_{\\min}|\\) 是语言的复杂度，与具体正则式写法无关。指数无穷就是「需要无限记忆的前缀」。后课封闭性证明常构造乘积自动机，再最小化只是工程；正确性不依赖最小。",-1)),a[6]||(a[6]=e("p",null,"不要用状态数比较 NFA 与 DFA 的「谁更强」：语言类相同，状态可以指数分开。",-1)),a[7]||(a[7]=e("p",null,"Hopcroft 划分从「接受/拒绝」两块出发，用字母表符号细化，直到稳定。实现是词法生成器的标准后段，本课要的是：最小状态数是 \\(L\\) 的不变量，与你怎么写正则式无关。NFA 状态数可以远小于 DFA，但不能拿来当 Myhill–Nerode 指数。",-1)),a[8]||(a[8]=e("p",null,"第一张图画「两条路各自如何到达最小 DFA」；这张拆开 Hopcroft 那条路的内部：以「以 aa 结尾」的三个状态 A、B、C（C 接受）为例，看划分细化的一轮里发生了什么。",-1)),(r(),n(s,null,{default:i(()=>[E(l,{id:"mermaid-56",class:"mermaid",graph:"flowchart%20TD%0A%20%20INIT%5B%22%E5%88%9D%E5%A7%8B%E5%88%92%E5%88%86%20%E6%8E%A5%E5%8F%97C%20%E4%B8%8E%20%E9%9D%9E%E6%8E%A5%E5%8F%97A%2CB%22%5D%20--%3E%20T1%5B%22%E7%94%A8%20a%20%E7%BB%86%E5%8C%96%3A%20A%E8%AF%BBa%E5%88%B0B%2C%20B%E8%AF%BBa%E5%88%B0C%22%5D%0A%20%20T1%20--%3E%20SPLIT%7B%22%E5%90%8C%E4%B8%80%E5%9D%97%E9%87%8C%E8%90%BD%E7%82%B9%E5%9C%A8%E4%B8%8D%E5%90%8C%E5%9D%97%3F%22%7D%0A%20%20SPLIT%20--%20%22%E6%98%AF%22%20--%3E%20NEW%5B%22A%20%E4%B8%8E%20B%20%E6%8B%86%E5%BC%80%3A%20%E5%BE%97%20A%2C%20B%2C%20C%22%5D%0A%20%20NEW%20--%3E%20T2%5B%22%E5%86%8D%E7%94%A8%20b%20%E6%A3%80%E6%9F%A5%E4%B8%80%E8%BD%AE%22%5D%0A%20%20T2%20--%3E%20STABLE%5B%22%E6%97%A0%E6%96%B0%E5%88%86%E8%A3%82%20%E5%88%92%E5%88%86%E7%A8%B3%E5%AE%9A%E5%8D%B3%E6%9C%80%E5%B0%8F%22%5D%0A"})]),fallback:i(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[9]||(a[9]=t('<p><span class="marginnote">常见误区：初学者容易把「合并状态」当成省内存的小优化。实际上少一个状态就会认错语言：最小状态数是语言本身的不变量，两个写法完全不同的正则式，最小化后的 DFA 必然同构——它更像语言的指纹，而不只是实现细节。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证 Hopcroft 算法的对数因子，不讨论 NFA 最小化的 PSPACE 性。不把 Myhill–Nerode 推广到树自动机。后课默认：正则 \\(\\iff\\) 有限指数右同余；谈「唯一最小 DFA」即这个对象。封闭性是下一课在运算下保持这一类。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>\\(\\sim_L\\) 有限指数当且仅当 \\(L\\) 正则；类即最小状态。</li><li>DFA 按可区分性商掉，结果唯一。</li><li>无穷多可区分前缀 \\(\\Rightarrow\\) 非正则，补泵引理。</li><li>出处：Nerode, 1958；Hopcroft, 1971。</li></ul>',5))])}const C=A(B,[["render",m]]);export{T as __pageData,C as default};
